  id: string
  title: string
  content: string
  createdAt: string
}

// In-memory store for demonstration. Replace with your database.
const posts: Post[] = []

export async function insertPost(data: {
  title: string
  content: string
}): Promise<Post> {
  const post: Post = {
    id: crypto.randomUUID(),
    title: data.title,
    content: data.content,
    createdAt: new Date().toISOString(),
  }
  posts.unshift(post)
  return post
}

// Cached posts list, tagged with "posts" so it can be invalidated on demand.
export const getPosts = unstable_cache(async () => [...posts], ['posts'], {
  tags: ['posts'],
})

